// futari-nx (2026-10-19): a game core's side of Renut's renderer (banjo_renut_select.h). Each core links its own copy
// of Futari's Direct3D; while Renut's renderer is chosen, the core's copies of the functions it replaces forward to the
// executable's entries (futari_renut_core_hooks.cpp, generated by tools/renut_futari_hooks.py; the core's own hooks in
// src/native/futari_native_core.cpp hand over with FUTARI_RENUT_CORE_YIELD). The executable's table comes through
// GetProcAddress on the PC (the core is a DLL) and through the final link on the Switch.
#pragma once

#include <cstdint>

#include <rex/hook.h>
#include <rex/ppc.h>

#include "futari_renut_hooks.h"

#if defined(_WIN32)
#ifndef WIN32_LEAN_AND_MEAN
#define WIN32_LEAN_AND_MEAN
#endif
#ifndef NOMINMAX
#define NOMINMAX
#endif
#include <windows.h>
#else
using FutariRenutEntryFn = void (*)(PPCContext&, uint8_t*);
extern "C" __attribute__((visibility("default"))) const FutariRenutEntryFn* FutariRenutEntries(uint32_t* count);
extern "C" __attribute__((visibility("default"))) void FutariRenutCallWithFree(uint32_t index, PPCContext* ctx,
                                                                               uint8_t* base, PPCFunc* xmemfree);
#endif

namespace futari::renut_core {

using Entry = void (*)(PPCContext&, uint8_t*);
using CallWithFree = void (*)(uint32_t, PPCContext*, uint8_t*, PPCFunc*);

struct Table {
  const Entry* entries = nullptr;  // null: Renut's renderer is not chosen
  CallWithFree call_with_free = nullptr;
};

inline const Table& Get() {
  static const Table table = [] {
    Table t;
    uint32_t count = 0;
#if defined(_WIN32)
    const HMODULE exe = GetModuleHandleW(nullptr);
    using GetEntries = const Entry* (*)(uint32_t*);
    const auto get = reinterpret_cast<GetEntries>(reinterpret_cast<void*>(GetProcAddress(exe, "FutariRenutEntries")));
    t.entries = get ? get(&count) : nullptr;
    t.call_with_free =
        reinterpret_cast<CallWithFree>(reinterpret_cast<void*>(GetProcAddress(exe, "FutariRenutCallWithFree")));
#else
    t.entries = FutariRenutEntries(&count);
    t.call_with_free = &FutariRenutCallWithFree;
#endif
    // A table of another build (another FUTARI_RENUT_CORE_ENTRIES) is not used.
    if (count != FUTARI_RENUT_CORE_COUNT || !t.call_with_free) t.entries = nullptr;
    return t;
  }();
  return table;
}

}  // namespace futari::renut_core

// The core's copy of the Direct3D function `name` at `address`.
#define FUTARI_RENUT_CORE_HOOK(address, name)                                          \
  extern "C" REX_FUNC(__imp__sub_##address);                                           \
  REX_HOOK_RAW(sub_##address) {                                                        \
    if (const auto* e = ::futari::renut_core::Get().entries) {                         \
      e[FUTARI_RENUT_CORE_INDEX_##name](ctx, base);                                    \
      return;                                                                          \
    }                                                                                  \
    __imp__sub_##address(ctx, base);                                                   \
  }

// The same for a function whose replacement may free the game's own memory: through the core's XMemFree at `free`.
#define FUTARI_RENUT_CORE_HOOK_FREE(address, name, free)                               \
  extern "C" REX_FUNC(__imp__sub_##address);                                           \
  extern "C" REX_FUNC(__imp__sub_##free);                                              \
  REX_HOOK_RAW(sub_##address) {                                                        \
    const auto& t = ::futari::renut_core::Get();                                       \
    if (t.entries) {                                                                   \
      t.call_with_free(FUTARI_RENUT_CORE_INDEX_##name, &ctx, base, &__imp__sub_##free); \
      return;                                                                          \
    }                                                                                  \
    __imp__sub_##address(ctx, base);                                                   \
  }

// First thing in futari_native_core.cpp's own hooks of a replaced function.
#define FUTARI_RENUT_CORE_YIELD(name)                                                  \
  if (const auto* e = ::futari::renut_core::Get().entries) {                           \
    e[FUTARI_RENUT_CORE_INDEX_##name](ctx, base);                                      \
    return;                                                                            \
  }
